select case when budget >= 3875000 then 'high' when budget >= 1257000 then 'mid' else 'low' end as budget_bucket, sum(case when location = 'Tokyo' then 1 else 0 end) as tokyo_count, sort_array(collect_set(location)) as location_list from departments where location in ('London', 'Tokyo', 'Berlin') group by case when budget >= 3875000 then 'high' when budget >= 1257000 then 'mid' else 'low' end having count(budget) >= 5 order by budget_bucket limit 5;
